provider "aws" {
    region = "us-west-1"
}

resource "aws_kms_key" "mykey" {
  description             = "This key is used to encrypt bucket objects"
  deletion_window_in_days = 10
}

resource "aws_s3_bucket" "mybucket" {
  bucket = "mybucket"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "example" {
  bucket = aws_s3_bucket.mybucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.mykey.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

responsePreview:
This Terraform configuration creates an AWS environment with:

- A customer-managed AWS KMS key with a configurable description and deletion window.
- An S3 bucket with a configurable name prefix and randomized suffix for deployability.
- Server-side encryption enabled on the S3 bucket using the KMS key ARN.
- The S3 encryption algorithm is set to `aws:kms`.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "kms_key_description" {
  description = "Description for the KMS key used to encrypt the S3 bucket."
  type        = string
  default     = "Customer managed KMS key for S3 bucket server-side encryption"
}

variable "kms_deletion_window_in_days" {
  description = "Number of days before the KMS key is deleted after destruction."
  type        = number
